import{_ as a,o as s,c as i,ai as e}from"./chunks/framework.iNbpOH0p.js";const g=JSON.parse('{"title":"HTTP 答案","description":"","frontmatter":{},"headers":[],"relativePath":"doc/2.Interview/Answer-5/11-HTTP.md","filePath":"doc/2.Interview/Answer-5/11-HTTP.md"}'),n={name:"doc/2.Interview/Answer-5/11-HTTP.md"};function r(l,t,d,h,o,p){return s(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="http-答案" tabindex="-1">HTTP 答案 <a class="header-anchor" href="#http-答案" aria-label="Permalink to “HTTP 答案”">​</a></h1><h2 id="一、http-协议基础" tabindex="-1">一、HTTP 协议基础 <a class="header-anchor" href="#一、http-协议基础" aria-label="Permalink to “一、HTTP 协议基础”">​</a></h2><h3 id="_1-3-http-协议与报文结构" tabindex="-1">1-3. HTTP 协议与报文结构 <a class="header-anchor" href="#_1-3-http-协议与报文结构" aria-label="Permalink to “1-3. HTTP 协议与报文结构”">​</a></h3><p><strong>问题</strong>：HTTP 协议是什么？请求报文和响应报文的结构是什么？</p><p><strong>答案</strong>：</p><p><strong>核心定义</strong>：HTTP（超文本传输协议）是应用层协议，基于 TCP/IP，用于客户端和服务器之间传输超文本。</p><p><strong>请求报文</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /api/users HTTP/1.1    ← 请求行（方法 + URL + 版本）</span></span>
<span class="line"><span>Host: example.com          ← 请求头</span></span>
<span class="line"><span>User-Agent: Mozilla/5.0</span></span>
<span class="line"><span>Accept: application/json</span></span>
<span class="line"><span>                           ← 空行</span></span>
<span class="line"><span>                           ← 消息体（GET 无）</span></span></code></pre></div><p><strong>响应报文</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.1 200 OK            ← 状态行</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>Content-Length: 123</span></span>
<span class="line"><span>                           ← 空行</span></span>
<span class="line"><span>{&quot;users&quot;: [...]}           ← 消息体</span></span></code></pre></div><hr><h2 id="二、http-方法" tabindex="-1">二、HTTP 方法 <a class="header-anchor" href="#二、http-方法" aria-label="Permalink to “二、HTTP 方法”">​</a></h2><h3 id="_4-9-http-请求方法与幂等性" tabindex="-1">4-9. HTTP 请求方法与幂等性 <a class="header-anchor" href="#_4-9-http-请求方法与幂等性" aria-label="Permalink to “4-9. HTTP 请求方法与幂等性”">​</a></h3><p><strong>问题</strong>：GET 与 POST 的区别是什么？什么是幂等性？</p><p><strong>答案</strong>：</p><p><strong>GET vs POST 对比</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>GET</th><th>POST</th></tr></thead><tbody><tr><td>用途</td><td>获取资源</td><td>创建资源</td></tr><tr><td>数据位置</td><td>URL 参数</td><td>请求体</td></tr><tr><td>可缓存</td><td>✅</td><td>❌</td></tr><tr><td>可收藏</td><td>✅</td><td>❌</td></tr><tr><td>幂等</td><td>✅</td><td>❌</td></tr></tbody></table><p><strong>幂等性</strong>：多次相同请求的结果与一次请求相同。</p><ul><li>✅ 幂等：GET、PUT、DELETE</li><li>❌ 不幂等：POST</li></ul><hr><h2 id="三、http-状态码" tabindex="-1">三、HTTP 状态码 <a class="header-anchor" href="#三、http-状态码" aria-label="Permalink to “三、HTTP 状态码”">​</a></h2><h3 id="_10-14-状态码分类" tabindex="-1">10-14. 状态码分类 <a class="header-anchor" href="#_10-14-状态码分类" aria-label="Permalink to “10-14. 状态码分类”">​</a></h3><p><strong>问题</strong>：HTTP 状态码分为哪几类？常见状态码有哪些？</p><p><strong>答案</strong>：</p><table tabindex="0"><thead><tr><th>分类</th><th>含义</th><th>常见状态码</th></tr></thead><tbody><tr><td>2xx</td><td>成功</td><td>200 OK、201 Created、204 No Content</td></tr><tr><td>3xx</td><td>重定向</td><td>301 永久、302 临时、304 未修改、307 临时</td></tr><tr><td>4xx</td><td>客户端错误</td><td>400 错误请求、401 未授权、403 禁止、404 未找到</td></tr><tr><td>5xx</td><td>服务器错误</td><td>500 内部错误、502 网关错误、503 不可用、504 超时</td></tr></tbody></table><hr><h2 id="四、http-头部" tabindex="-1">四、HTTP 头部 <a class="header-anchor" href="#四、http-头部" aria-label="Permalink to “四、HTTP 头部”">​</a></h2><h3 id="_15-18-常见-http-头部" tabindex="-1">15-18. 常见 HTTP 头部 <a class="header-anchor" href="#_15-18-常见-http-头部" aria-label="Permalink to “15-18. 常见 HTTP 头部”">​</a></h3><p><strong>问题</strong>：常见的请求头/响应头有哪些？Content-Type 有哪些值？</p><p><strong>答案</strong>：</p><p><strong>常见请求头</strong>：</p><ul><li><code>Content-Type</code>：请求体类型</li><li><code>Accept</code>：期望的响应类型</li><li><code>Authorization</code>：认证信息</li><li><code>Cookie</code>：携带的 Cookie</li></ul><p><strong>Content-Type 常见值</strong>：</p><ul><li><code>application/json</code></li><li><code>application/x-www-form-urlencoded</code></li><li><code>multipart/form-data</code></li><li><code>text/html</code></li></ul><hr><h2 id="五、cookie-与-session" tabindex="-1">五、Cookie 与 Session <a class="header-anchor" href="#五、cookie-与-session" aria-label="Permalink to “五、Cookie 与 Session”">​</a></h2><h3 id="_19-24-cookie、session、token" tabindex="-1">19-24. Cookie、Session、Token <a class="header-anchor" href="#_19-24-cookie、session、token" aria-label="Permalink to “19-24. Cookie、Session、Token”">​</a></h3><p><strong>问题</strong>：Cookie 和 Session 的区别是什么？JWT 是什么？</p><p><strong>答案</strong>：</p><p><strong>对比表格</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>Cookie</th><th>Session</th><th>JWT</th></tr></thead><tbody><tr><td>存储</td><td>客户端</td><td>服务器</td><td>客户端</td></tr><tr><td>安全性</td><td>较低</td><td>较高</td><td>高</td></tr><tr><td>扩展性</td><td>差</td><td>差</td><td>好</td></tr></tbody></table><p><strong>Cookie 属性</strong>：</p><ul><li><code>HttpOnly</code>：禁止 JS 访问（防 XSS）</li><li><code>Secure</code>：仅 HTTPS 传输</li><li><code>SameSite</code>：限制跨域发送</li></ul><p><strong>JWT 结构</strong>：Header.Payload.Signature</p><hr><h2 id="六、http-缓存" tabindex="-1">六、HTTP 缓存 <a class="header-anchor" href="#六、http-缓存" aria-label="Permalink to “六、HTTP 缓存”">​</a></h2><h3 id="_25-29-http-缓存机制" tabindex="-1">25-29. HTTP 缓存机制 <a class="header-anchor" href="#_25-29-http-缓存机制" aria-label="Permalink to “25-29. HTTP 缓存机制”">​</a></h3><p><strong>问题</strong>：什么是强缓存？什么是协商缓存？区别是什么？</p><p><strong>答案</strong>：</p><p><strong>对比表格</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>强缓存</th><th>协商缓存</th></tr></thead><tbody><tr><td>判断方式</td><td>Cache-Control、Expires</td><td>ETag、Last-Modified</td></tr><tr><td>状态码</td><td>200 (from cache)</td><td>304 Not Modified</td></tr><tr><td>请求服务器</td><td>否</td><td>是</td></tr></tbody></table><p><strong>缓存流程</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>强缓存命中 → 返回 200 (from cache)</span></span>
<span class="line"><span>强缓存未命中 → 发送请求 → 协商缓存命中 → 返回 304</span></span>
<span class="line"><span>                            → 协商缓存未命中 → 返回 200 + 新资源</span></span></code></pre></div><hr><h2 id="七、https" tabindex="-1">七、HTTPS <a class="header-anchor" href="#七、https" aria-label="Permalink to “七、HTTPS”">​</a></h2><h3 id="_30-35-https-工作原理" tabindex="-1">30-35. HTTPS 工作原理 <a class="header-anchor" href="#_30-35-https-工作原理" aria-label="Permalink to “30-35. HTTPS 工作原理”">​</a></h3><p><strong>问题</strong>：HTTPS 与 HTTP 的区别是什么？SSL/TLS 握手过程是怎样的？</p><p><strong>答案</strong>：</p><p><strong>HTTPS = HTTP + SSL/TLS 加密</strong></p><p><strong>TLS 握手过程</strong>：</p><ol><li>客户端发送 ClientHello（支持的加密套件）</li><li>服务器返回 ServerHello + 数字证书</li><li>客户端验证证书，生成会话密钥，用公钥加密</li><li>服务器用私钥解密，双方使用会话密钥通信</li></ol><p><strong>加密方式</strong>：</p><ul><li>非对称加密：交换会话密钥（RSA、ECDHE）</li><li>对称加密：传输数据（AES）</li></ul><hr><h2 id="八、http-2-与-http-3" tabindex="-1">八、HTTP/2 与 HTTP/3 <a class="header-anchor" href="#八、http-2-与-http-3" aria-label="Permalink to “八、HTTP/2 与 HTTP/3”">​</a></h2><h3 id="_36-39-http-版本对比" tabindex="-1">36-39. HTTP 版本对比 <a class="header-anchor" href="#_36-39-http-版本对比" aria-label="Permalink to “36-39. HTTP 版本对比”">​</a></h3><p><strong>问题</strong>：HTTP/1.0、HTTP/1.1、HTTP/2 的区别是什么？队头阻塞如何解决？</p><p><strong>答案</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>HTTP/1.1</th><th>HTTP/2</th><th>HTTP/3</th></tr></thead><tbody><tr><td>传输层</td><td>TCP</td><td>TCP</td><td>QUIC (UDP)</td></tr><tr><td>多路复用</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>头部压缩</td><td>❌</td><td>HPACK</td><td>QPACK</td></tr><tr><td>服务器推送</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>队头阻塞</td><td>TCP 级</td><td>TCP 级</td><td>无</td></tr></tbody></table><hr><h2 id="九、跨域" tabindex="-1">九、跨域 <a class="header-anchor" href="#九、跨域" aria-label="Permalink to “九、跨域”">​</a></h2><h3 id="_40-47-跨域解决方案" tabindex="-1">40-47. 跨域解决方案 <a class="header-anchor" href="#_40-47-跨域解决方案" aria-label="Permalink to “40-47. 跨域解决方案”">​</a></h3><p><strong>问题</strong>：什么是同源策略？跨域解决方案有哪些？CORS 是什么？</p><p><strong>答案</strong>：</p><p><strong>同源策略</strong>：协议、域名、端口都相同。</p><p><strong>CORS 配置</strong>：</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 服务器设置响应头</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Access</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Allow</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Origin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Access</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Allow</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Methods</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">POST</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Access</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Allow</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Headers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Content</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Type</span></span></code></pre></div><p><strong>简单请求</strong>：直接发送 <strong>预检请求</strong>：先发送 OPTIONS 请求，确认后再发送实际请求</p><hr><h2 id="十、tcp-ip" tabindex="-1">十、TCP/IP <a class="header-anchor" href="#十、tcp-ip" aria-label="Permalink to “十、TCP/IP”">​</a></h2><h3 id="_48-51-tcp-三次握手与四次挥手" tabindex="-1">48-51. TCP 三次握手与四次挥手 <a class="header-anchor" href="#_48-51-tcp-三次握手与四次挥手" aria-label="Permalink to “48-51. TCP 三次握手与四次挥手”">​</a></h3><p><strong>问题</strong>：TCP 与 UDP 的区别是什么？三次握手和四次挥手的过程是什么？</p><p><strong>答案</strong>：</p><p><strong>TCP vs UDP</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>TCP</th><th>UDP</th></tr></thead><tbody><tr><td>连接</td><td>面向连接</td><td>无连接</td></tr><tr><td>可靠</td><td>✅</td><td>❌</td></tr><tr><td>速度</td><td>慢</td><td>快</td></tr></tbody></table><p><strong>三次握手</strong>：SYN → SYN+ACK → ACK <strong>四次挥手</strong>：FIN → ACK → FIN → ACK</p><hr><h2 id="十三、安全" tabindex="-1">十三、安全 <a class="header-anchor" href="#十三、安全" aria-label="Permalink to “十三、安全”">​</a></h2><h3 id="_60-62-xss、csrf、点击劫持" tabindex="-1">60-62. XSS、CSRF、点击劫持 <a class="header-anchor" href="#_60-62-xss、csrf、点击劫持" aria-label="Permalink to “60-62. XSS、CSRF、点击劫持”">​</a></h3><p><strong>问题</strong>：什么是 XSS 攻击？如何防范？什么是 CSRF 攻击？</p><p><strong>答案</strong>：</p><p><strong>XSS（跨站脚本攻击）</strong>：注入恶意脚本</p><ul><li>防御：转义输入、CSP、HttpOnly Cookie</li></ul><p><strong>CSRF（跨站请求伪造）</strong>：利用已登录身份发送请求</p><ul><li>防御：CSRF Token、SameSite Cookie、验证 Referer</li></ul><p><strong>点击劫持</strong>：透明 iframe 覆盖诱导点击</p><ul><li>防御：X-Frame-Options、CSP</li></ul><hr><h2 id="十四、其他" tabindex="-1">十四、其他 <a class="header-anchor" href="#十四、其他" aria-label="Permalink to “十四、其他”">​</a></h2><h3 id="_63-从输入网址到页面呈现的完整过程" tabindex="-1">63. 从输入网址到页面呈现的完整过程 <a class="header-anchor" href="#_63-从输入网址到页面呈现的完整过程" aria-label="Permalink to “63. 从输入网址到页面呈现的完整过程”">​</a></h3><p><strong>问题</strong>：从输入网址到页面呈现的完整过程是什么？</p><p><strong>答案</strong>：</p><ol><li>DNS 解析域名 → IP 地址</li><li>TCP 三次握手建立连接</li><li>TLS 握手（HTTPS）</li><li>发送 HTTP 请求</li><li>服务器处理请求，返回响应</li><li>浏览器解析 HTML → 构建 DOM 树</li><li>解析 CSS → 构建 CSSOM 树</li><li>合并为渲染树</li><li>布局（计算位置大小）</li><li>绘制（渲染到屏幕）</li></ol>`,103)])])}const c=a(n,[["render",r]]);export{g as __pageData,c as default};
